// inventory · кейсы inv-02, inv-03, inv-05, inv-06, inv-07 (.qa/tests/inventory/) — מחזור מלאי на своём товаре QA-AUTO.
// #d7b7ec74 (עבר QA 2026-10-07, отменяет #0309a9bf): окно блока ведёт к «הסרה מהמקום»; после неё — обычное окно удаления
// без «…ייגרעו מהמלאי…», в «יומן תנועות» есть «ללא מקום · C-03 ← ללא מקום», записи «מחיקת מוצר · … נגרע מהמלאי» НЕТ.
// Создаёт товар «QA-AUTO-inventory-<ts>», кладёт 5 шт. в СУЩЕСТВУЮЩУЮ ячейку C-03 (карта склада не меняется),
// buyer заказывает 2 шт., admin утверждает, «עובד מחסן בדיקה» (через «כניסה כעובד») комплектует.
// Реальные товары, их остатки и пороги не трогаются.
// afterAll: заказ — «דחייה» с «QA-AUTO cleanup», если ещё ממתינה, иначе довести до «סופק»; ячейку освободить
// («הסרה מהמקום» на карте) и удалить товар.
// ⚠️ Корзина buyer общая на сервере → НЕ запускать параллельно с orders/order-lifecycle.spec.ts и client-ordering/cart-checkout.spec.ts.
import { test, expect, Page, Browser } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const TS = Date.now().toString().slice(-7);
const P = `QA-AUTO-inventory-${TS}`;
const SKU = `QA-AUTO-INV-${TS}`;
const PLACE = 'המחסן שלנו · ארון C · מדף 3 (C-03)'; // существующая ячейка
const CELL = 'C-03';
const WORKER = 'עובד מחסן בדיקה';
const state: { productId?: string; orderNo?: string; orderUrl?: string; pickUrl?: string } = {};

// ---------- helpers ----------
async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
}

/** /catalog с поиском по QA-товару (admin: «קטלוג וניהול», עובד מחסן: «ניהול מלאי»). */
async function findProduct(page: Page) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: /^(קטלוג וניהול|ניהול מלאי)$/ })).toBeVisible({ timeout: 20_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
  await expect(qtyBtn(page)).toBeVisible({ timeout: 20_000 });
}
const qtyBtn = (page: Page) => page.getByRole('button', { name: `קליטת מלאי — ${P}`, exact: true });
const minBtn = (page: Page) => page.getByRole('button', { name: `עדכון רף מינימום — ${P}`, exact: true });
const row = (page: Page) => qtyBtn(page).locator('xpath=ancestor::*[.//button[@aria-label="פעולות"]][1]');

async function expectStock(page: Page, qty: number) {
  await findProduct(page);
  await expect(qtyBtn(page)).toHaveText(String(qty), { timeout: 15_000 });
}

async function setMin(page: Page, value: number) {
  await minBtn(page).click();
  const input = page.getByRole('spinbutton', { name: `רף מינימום — ${P}` });
  await input.fill(String(value));
  await input.press('Enter');
  await expect(minBtn(page)).toHaveText(String(value), { timeout: 15_000 });
}

async function emptyCart(page: Page) {
  await page.goto('/shop/cart');
  await expect(page.getByRole('heading', { name: 'העגלה שלי' })).toBeVisible();
  const remove = page.getByRole('button', { name: /^הסרה מהעגלה/ });
  // ждём, пока корзина загрузится (staging бывает медленным): либо есть позиции, либо «העגלה ריקה»
  await expect(remove.first().or(page.getByText('העגלה ריקה'))).toBeVisible({ timeout: 20_000 });
  while (await remove.count()) {
    await remove.first().click();
    await page.waitForTimeout(500);
  }
  await expect(page.getByText('העגלה ריקה')).toBeVisible();
}

async function buyerPlaceOrder(browser: Browser, qty: number, note: string): Promise<string> {
  const ctx = await browser.newContext({ storageState: auth('buyer'), locale: 'he-IL' });
  const page = await ctx.newPage();
  try {
    await emptyCart(page);
    await page.goto(`/shop/p/${state.productId}`);
    await page.getByRole('button', { name: /^הוסף לעגלה/ }).click();
    await page.goto('/shop/cart');
    for (let i = 1; i < qty; i++) await page.getByRole('button', { name: `הוספת יחידה — ${P}` }).click();
    await expect(page.getByText('סה״כ משוער').locator('..')).toContainText(`₪${(qty * 9.5).toFixed(2)}`);
    await page.getByRole('button', { name: 'המשך לביצוע הזמנה' }).click();
    await page.getByRole('textbox', { name: 'הערות להזמנה' }).fill(note);
    await page.getByRole('button', { name: 'שליחת הזמנה' }).click();
    await expect(page.getByRole('heading', { name: 'ההזמנה נקלטה!' })).toBeVisible({ timeout: 20_000 });
    return (await page.getByText(/^הזמנה\s*#\d+/).first().innerText()).match(/#(\d+)/)![1];
  } finally {
    await ctx.close();
  }
}

const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');

async function openOrder(page: Page, no: string) {
  if (state.orderUrl) {
    await page.goto(state.orderUrl);
  } else {
    await page.goto('/orders');
    await page.getByRole('combobox', { name: 'סינון לפי חודש' }).selectOption({ label: 'כל החודשים' });
    await page.getByRole('button', { name: new RegExp(`^#${no} `) }).click();
  }
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 20_000 });
  state.orderUrl = page.url();
}

/** Освободить ячейку через карту (из диалога блокировки удаления) и удалить товар.
 *  blockQty задан (тест) — проверяются тексты окон #d7b7ec74; без него (afterAll) — только уборка, без проверок текста. */
async function deleteProduct(page: Page, blockQty?: number) {
  const strict = blockQty !== undefined;
  await findProduct(page);
  await row(page).getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: /^מחיקה/ }).click();
  let dlg = page.getByRole('dialog');
  // ждём, пока диалог отрисуется (один из двух вариантов), прежде чем проверять, какой именно
  await expect(
    dlg.getByRole('heading', { name: 'לא ניתן למחוק מוצר עם מלאי' }).or(dlg.getByRole('heading', { name: 'מחיקת מוצר' })),
  ).toBeVisible({ timeout: 20_000 });
  if (await dlg.getByRole('heading', { name: 'לא ניתן למחוק מוצר עם מלאי' }).isVisible().catch(() => false)) {
    // #d17c625a (12.10): «"<שם>" — משויך למקום במחסן, ורשומות בו עדיין N.» + строка «<קוד> · N» + путь через «הסרה מהמקום»
    if (strict) {
      await expect(dlg).toContainText(P);
      await expect(dlg).toContainText(/— משויך למקום במחסן, ורשומ(ות|ה) בו עדיין (\d+|יחידה אחת)\./);
      if (blockQty! > 1) await expect(dlg).toContainText(`— משויך למקום במחסן, ורשומות בו עדיין ${blockQty}.`);
      await expect(dlg.getByRole('listitem').filter({ hasText: CELL })).toContainText(new RegExp(`${CELL}\\s*· ${blockQty}$`));
      await expect(dlg).toContainText('«הסרה מהמקום», ואז ניתן יהיה למחוק את המוצר.');
      await expect(dlg).not.toContainText('העברה למקום אחר');
      await expect(dlg.getByRole('button', { name: 'סגירה' })).toBeVisible();
      await expect(dlg.getByRole('button', { name: 'מחיקה', exact: true })).toHaveCount(0);
    }
    await dlg.getByRole('button', { name: 'מעבר למפת המחסן' }).click();
    await expect(page).toHaveURL(/\/warehouse\/map/);
    // карта открыта с выбранным местом: товар в списке «פריטים במדף»
    const item = page.getByRole('listitem').filter({ hasText: P });
    await expect(item).toBeVisible({ timeout: 20_000 });
    if (strict) await expect(page.getByText(CELL, { exact: true }).first()).toBeVisible();
    await item.getByRole('button', { name: 'הסרה מהמקום' }).click();
    dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הסרת המוצר מהמקום' })).toBeVisible();
    if (strict) {
      await expect(dlg).toContainText(`להסיר את «${P}» ממקום זה?`);
      await expect(dlg).toContainText('המוצר יישאר במלאי, ללא מקום במחסן');
    }
    await dlg.getByRole('button', { name: 'הסרה', exact: true }).click();
    await expect(page.getByRole('listitem').filter({ hasText: P })).toHaveCount(0, { timeout: 15_000 });

    await findProduct(page);
    await expect(row(page)).toContainText('ללא מיקום');
    await row(page).getByRole('button', { name: 'פעולות' }).click();
    const del = page.getByRole('menuitem', { name: /^מחיקה/ });
    if (strict) await expect(del).not.toContainText('יש מלאי במחסן'); // #98be590c
    await del.click();
    dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible();
    // #d7b7ec74: обычное окно, абзаца «במחסן רשומות N ללא מקום. עם המחיקה הן ייגרעו מהמלאי…» нет
    if (strict) {
      await expect(dlg).toContainText(new RegExp(`האם למחוק את \\W?"${P}"\\W?\\?`)); // имя в bidi-изоляторах
      await expect(dlg).toContainText('הפעולה אינה ניתנת לביטול.');
      await expect(dlg).not.toContainText('ייגרעו');
      await expect(dlg).not.toContainText('במחסן רשומות');
    }
  }
  await expect(dlg.getByRole('heading', { name: 'מחיקת מוצר' })).toBeVisible();
  await dlg.getByRole('button', { name: 'מחיקה', exact: true }).click();
  await expect(page.getByText(/הוסר מהקטלוג\. ההזמנות והתנועות שמזכירות אותו נשמרו\./)).toBeVisible({ timeout: 15_000 });
}

/** «יומן תנועות» на карте склада после удаления (#d7b7ec74): есть «ללא מקום · C-03 ← ללא מקום · test admin · qty»
 *  (от «הסרה מהמקום»), записи «מחיקת מוצר · ללא מקום ← נגרע מהמלאי» НЕТ. */
async function expectUnplaceButNoDeletionInJournal(page: Page, qty: number) {
  await page.goto('/warehouse/map');
  await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 20_000 });
  const expand = page.getByRole('button', { name: 'פתיחת יומן התנועות' });
  if (await expand.isVisible().catch(() => false)) await expand.click();
  await page.getByRole('textbox', { name: 'חיפוש ביומן התנועות' }).fill(P);
  const entry = (kind: string) =>
    page.getByText(kind, { exact: true }).and(page.locator(':not([role="tab"])'))
      .locator(`xpath=ancestor::div[.//*[contains(normalize-space(), "${P}")]][1]`);
  const unplace = entry('ללא מקום');
  await expect(unplace).toHaveCount(1, { timeout: 20_000 });
  await expect(unplace).toContainText(CELL);
  await expect(unplace).toContainText('test admin');
  await expect(unplace).toContainText(String(qty));
  await expect(entry('מחיקת מוצר')).toHaveCount(0);
  await expect(page.getByText(/נגרע מהמלאי/)).toHaveCount(0);
}

// ---------- tests ----------
test.describe('inventory — מחזור מלאי: קליטה, רף, הזמנה, ליקוט (QA-AUTO)', () => {
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL' });
    const page = await ctx.newPage();
    try {
      if (state.orderNo) {
        await openOrder(page, state.orderNo);
        if (await page.getByRole('button', { name: 'דחייה' }).count()) {
          await page.getByRole('button', { name: 'דחייה' }).click();
          const dlg = page.getByRole('dialog');
          await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup');
          await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
          await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
        } else {
          for (const step of ['סמן כמוכנה למשלוח', 'סמן כיצאה למשלוח', 'סמן כסופקה']) {
            const btn = page.getByRole('button', { name: step });
            if ((await btn.count()) && (await btn.isEnabled())) {
              await btn.click();
              await page.waitForTimeout(1500);
            }
          }
        }
      }
      await page.goto('/catalog');
      await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
      // ждём реальный результат поиска: строка товара либо «ничего не найдено»
      await expect(qtyBtn(page).or(page.getByText('לא נמצאו מוצרים התואמים לסינון'))).toBeVisible({ timeout: 20_000 });
      if (await qtyBtn(page).count()) await deleteProduct(page);
    } finally {
      await ctx.close();
    }
  });

  test('מוצר QA חדש: כמות 0 → «אזל», רף ברירת מחדל 10 #6a70b149 #6a84687f @desktop', async ({ page }) => {
    await page.goto('/catalog/new');
    await expect(page.getByRole('heading', { level: 1, name: 'מוצר חדש' })).toBeVisible();
    await page.getByRole('textbox', { name: /שם מוצר/ }).fill(P);
    await page.getByRole('textbox', { name: /מק"ט/ }).fill(SKU);
    await page.getByRole('spinbutton', { name: 'מחיר בסיס' }).fill('9.5');
    await page.getByRole('button', { name: 'שמירה', exact: true }).click();
    await expect(page.getByText('נוסף לקטלוג.')).toBeVisible({ timeout: 15_000 });

    await findProduct(page);
    await expect(qtyBtn(page)).toHaveText('0');
    await expect(minBtn(page)).toHaveText('10');
    await expect(row(page)).toContainText('אזל');
    await expect(row(page)).toContainText('ללא מיקום');
    await page.getByRole('button', { name: P, exact: true }).click();
    await expect(page).toHaveURL(/\/edit$/);
    state.productId = page.url().match(/catalog\/([0-9a-f-]{36})\/edit/)![1];
  });

  test('קליטה בלחיצה על הכמות לתא קיים: מוצר נבחר, «כמות», טוסט, מיקום, «מלאי נמוך» #6a858f15 #6a8466f2 #6a5cb979 @desktop', async ({ page }) => {
    test.skip(!state.productId, 'товар не создан');
    await findProduct(page);
    await qtyBtn(page).click();
    const dlg = page.getByRole('dialog');
    await expect(dlg.getByRole('heading', { name: 'הוספת פריט למלאי' })).toBeVisible();
    await expect(dlg).toContainText(`${P} — בחרו כמות, ומקום אם הוא ידוע`);
    await dlg.getByRole('combobox', { name: 'מקום היעד' }).selectOption({ label: PLACE });
    const qty = dlg.getByRole('spinbutton', { name: 'כמות', exact: true });
    await expect(dlg).not.toContainText("יח'");
    await expect(dlg.getByRole('button', { name: 'הוספה' })).toBeDisabled();
    await qty.fill('5');
    await dlg.getByRole('button', { name: 'הוספה' }).click();
    await expect(page.getByText(new RegExp(`^5 של .*${P}.* נקלטו למדף ${CELL}\\.$`))).toBeVisible({ timeout: 15_000 });

    await expectStock(page, 5);
    await expect(row(page)).toContainText(CELL);
    await expect(row(page)).toContainText('ארון C | מדף 3');
    await expect(row(page)).toContainText('מלאי נמוך'); // 5 ≤ 10
  });

  test('עריכה מהירה של רף מינימום: 2 → «במלאי» ונשמר; 5 = כמות → «מלאי נמוך» #6a846775 #6a748a64 @desktop', async ({ page }) => {
    test.skip(!state.productId, 'товар не создан');
    await findProduct(page);
    await setMin(page, 2);
    await expect(row(page)).toContainText('במלאי');
    await expect(minBtn(page)).not.toContainText('יח');

    await findProduct(page); // после перезагрузки
    await expect(minBtn(page)).toHaveText('2');
    await expect(row(page)).toContainText('במלאי');

    await setMin(page, 5);
    await expect(row(page)).toContainText('מלאי נמוך');
  });

  test('הזמנת לקוח ואישור — המלאי לא משתנה, אין «לאחר הזמנה» #6a7494e8 @desktop', async ({ page, browser }) => {
    test.skip(!state.productId, 'товар не создан');
    test.setTimeout(120_000);
    state.orderNo = await buyerPlaceOrder(browser, 2, `QA-AUTO-inventory-e2e-${TS}`);

    await openOrder(page, state.orderNo);
    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    const dlg = page.getByRole('dialog');
    await dlg.getByRole('textbox', { name: 'הערה (לא חובה)' }).fill('QA-AUTO approve (inventory e2e)');
    await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 20_000 });

    await expectStock(page, 5);
    await expect(page.getByText(/לאחר הזמנה|אחרי הזמנה/)).toHaveCount(0);
  });

  test('עובד מחסן: המלאי יורד רק אחרי «לוקט», ללא ניכוי כפול בסיום הליקוט #6a7494e8 @desktop', async ({ page }) => {
    test.skip(!state.orderNo, 'заказ не создан');
    test.setTimeout(120_000);
    await impersonate(page, WORKER);
    await page.goto('/warehouse/picking');
    await expect(page.getByRole('heading', { level: 1, name: 'ליקוט וניתוב' })).toBeVisible({ timeout: 20_000 });
    await page.getByRole('button', { name: new RegExp(`^הזמנה #${state.orderNo} `) }).click();
    await expect(page.getByRole('heading', { name: `הזמנה #${state.orderNo}` })).toBeVisible();
    await page.getByRole('button', { name: 'התחלת ליקוט' }).click();
    await expect(page.getByRole('heading', { level: 1, name: 'רשימת ליקוט' })).toBeVisible({ timeout: 20_000 });
    state.pickUrl = page.url();

    await expectStock(page, 5); // «בליקוט» — ещё не списано

    await page.goto(state.pickUrl);
    const item = page.getByRole('listitem').filter({ hasText: P });
    await expect(item).toContainText(CELL);
    await item.getByRole('button', { name: 'לוקט', exact: true }).click();
    await expect(page.getByText('1/1', { exact: true }).first()).toBeVisible({ timeout: 15_000 });

    await expectStock(page, 3); // 5 − 2

    await page.goto(state.pickUrl);
    await page.getByRole('button', { name: 'סיום ליקוט' }).click();
    await expect(page.getByText('הליקוט הושלם — ההזמנה סומנה «לוקטה»')).toBeVisible({ timeout: 20_000 });

    await expectStock(page, 3); // без повторного списания
    await backToAdmin(page);
  });

  test('admin: אחרי הליקוט ההזמנה «מוכן למשלוח», ליקוט 1/1 → «סופק» #6a7494e8 @desktop', async ({ page }) => {
    test.skip(!state.orderNo, 'заказ не создан');
    await openOrder(page, state.orderNo!);
    await expect(header(page)).toContainText('מוכנה למשלוח', { timeout: 20_000 });
    await expect(page.getByText('כל הפריטים לוקטו במלואם.')).toBeVisible();
    await page.getByRole('button', { name: 'סמן כיצאה למשלוח' }).click();
    await expect(header(page)).toContainText('בדרך ללקוח', { timeout: 15_000 });
    await page.getByRole('button', { name: 'סמן כסופקה' }).click();
    await expect(header(page)).toContainText('סופקה', { timeout: 15_000 });
    await expectStock(page, 3);
  });

  test('מחיקה חסומה כשיש מלאי במקום («משויך למקום במחסן: רשומות עדיין 3», «הסרה מהמקום») → מפה עם המקום → «הסרה מהמקום» → חלון מחיקה רגיל בלי «ייגרעו» → נמחק; ביומן «ללא מקום», בלי «מחיקת מוצר» #6a5cb979 #d7b7ec74 @desktop', async ({ page }) => {
    test.skip(!state.productId, 'товар не создан');
    await deleteProduct(page, 3);
    await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(P);
    await expect(qtyBtn(page)).toHaveCount(0, { timeout: 15_000 });
    // остаток после ליקוט — 3 (5 − 2): «הסרה מהמקום» записана, удаление — без записи «נגרע מהמלאי» (#d7b7ec74)
    await expectUnplaceButNoDeletionInJournal(page, 3);
  });
});
